schemaText:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "version",
    "values"
  ],
  "properties": {
    "$schema": {
      "type": "string"
    },
    "version": {
      "const": 1
    },
    "values": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "gravity": {
          "type": "number",
          "minimum": 8,
          "maximum": 50,
          "description": "Downward acceleration for frames and grenades."
        },
        "boostScale": {
          "type": "number",
          "minimum": 0.5,
          "maximum": 2,
          "description": "Multiplier on boost speeds."
        },
        "debrisRigidBodies": {
          "type": "integer",
          "minimum": 0,
          "maximum": 160,
          "description": "Maximum simultaneously simulated debris bodies."
        },
        "cameraShoulder": {
          "type": "number",
          "minimum": -3,
          "maximum": 3,
          "description": "Sideways offset of the look target."
        },
        "timeOfDay": {
          "type": "number",
          "minimum": 0,
          "maximum": 23.99,
          "description": "Local solar hour."
        },
        "tiny": {
          "type": "number",
          "minimum": 1e-7,
          "maximum": 0.000001,
          "description": "Very small bounds."
        }
      }
    }
  }
}

